import subprocess,json,datetime
code='import json,time,datetime,urllib.parse\nfrom playwright.sync_api import sync_playwright\ndef urlclean(u):\n p=urllib.parse.urlparse(u);return p.scheme+\'://\'+p.netloc+p.path\nwith sync_playwright() as pw:\n browser=pw.chromium.connect_over_cdp(\'http://127.0.0.1:9222\',timeout=10000)\n pages=[p for c in browser.contexts for p in c.pages]\n import pathlib,hashlib\n page=next(p for p in pages if \'firefly.adobe.com\' in p.url)\n model=page.locator(\'sp-picker#model\');size=page.locator(\'sp-picker#size\')\n info={\'model_value\':model.get_attribute(\'value\'),\'model_text\':model.locator(\'button#button\').inner_text(),\'size_value\':size.get_attribute(\'value\'),\'size_text\':size.locator(\'button#button\').inner_text(),\'accessibility\':page.locator(\'body\').aria_snapshot(),\'generate_enabled\':page.get_by_role(\'button\',name=\'Generate\',exact=True).is_enabled()}\n print(json.dumps({\'selection\':info},ensure_ascii=False))\n assert \'flare\' in info[\'model_text\'].lower() and (\'1:1\' in info[\'size_text\'] or \'square\' in info[\'size_text\'].lower()) and info[\'generate_enabled\']\n assert page.get_by_role(\'textbox\',name=\'Prompt\',exact=True).inner_text().strip()==\'A simple red apple on a plain white background.\'\n token=json.loads(pathlib.Path(\'/tmp/selected-web-token.json\').read_text())[\'token\']\n result=page.evaluate(\'\'\'async token => {const p=await fetch(\'https://ims-na1.adobelogin.com/ims/profile/v1\',{headers:{Authorization:\'Bearer \'+token,\'X-Client-Id\':\'clio-playground-web\'}});let d={};try{d=await p.json()}catch{};const r=await fetch(\'https://api.ipify.org?format=json\');const ip=await r.json();return {profile_status:p.status,email:d.email||\'\',ip:ip.ip}}\'\'\',token)\n verified=result[\'profile_status\']==200 and result[\'email\'].lower()==\'ashleychambers2212@outlook.com\'\n ip_hash=hashlib.sha256(result[\'ip\'].encode()).hexdigest()[:24]\n assert verified and ip_hash==\'638eac0873f490f664d2754e\'\n out={\'at\':datetime.datetime.now(datetime.timezone.utc).isoformat(),\'model\':\'gpt-image-2.5-flare\',\'model_ui_text\':info[\'model_text\'],\'model_value\':info[\'model_value\'],\'size_text\':info[\'size_text\'],\'size_value\':info[\'size_value\'],\'verified_identity\':True,\'profile_status\':200,\'ip_hash\':ip_hash,\'generate_button\':\'Generate\'}\n pathlib.Path(\'/control/web-model-ready.json\').write_text(json.dumps(out,ensure_ascii=False));print(json.dumps({\'ready\':out},ensure_ascii=False))\n\n result=[]\n for c in browser.contexts:\n  for p in c.pages:\n   if p.is_closed():continue\n   try:\n    body=p.locator(\'body\').inner_text(timeout=6000)[:14000]\n    controls=p.locator(\'button,input,textarea,select,[role="combobox"],[role="textbox"]\').evaluate_all(\'(els)=>els.map(e=>({tag:e.tagName,role:e.getAttribute("role"),type:e.type,id:e.id,name:e.getAttribute("name"),text:e.innerText?.slice(0,140),placeholder:e.getAttribute("placeholder"),aria:e.getAttribute("aria-label")}))\')\n    result.append({\'url\':urlclean(p.url),\'title\':p.title(),\'text\':body,\'controls\':controls})\n   except Exception as e:result.append({\'url\':urlclean(p.url),\'error_class\':type(e).__name__})\n print(json.dumps({\'pages\':result},ensure_ascii=False))\n'
r=subprocess.run(['docker','exec','adobe-three-arm-web-20261027','python','-c',code],capture_output=True,text=True,timeout=95)
print(json.dumps({'at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'returncode':r.returncode,'browser':[json.loads(x) for x in r.stdout.splitlines() if x.startswith('{')],'error_class':'browser_command_failed' if r.returncode else None,'error_tail':r.stderr[-650:] if r.returncode else None},ensure_ascii=False))

import pathlib
root=pathlib.Path("/opt/adobe-relay/releases/three-arm-20261027")
if r.returncode==0:(root/"web-model-ready.json").write_text((root/"control/web-model-ready.json").read_text())
